INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Drucker Funktion, Einsatz, Varianten > LED-Drucker
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können LED-Drucker unabhängig von der Toner-Kompatibilität ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Drucker benötigen spezifischen Toner"}, {"text": "Ja", "correct": false, "because": "Inkompatibilität verhindert Druck"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Auswahl eines LED-Druckers immer die Druckvolumen-Anforderungen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Volumen beeinflusst Eignung und Kosten"}, {"text": "Nein", "correct": false, "because": "Anforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Druckgeschwindigkeit eines LED-Druckers für alle Anwendungen irrelevant?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit wichtig bei hohem Volumen"}, {"text": "Ja", "correct": false, "because": "Beeinflusst Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Können LED-Drucker ohne Rücksicht auf die Energieeffizienz ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Effizienz ist Vorteil von LED"}, {"text": "Ja", "correct": false, "because": "Energieverbrauch ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind LED-Drucker immer kompakter als Laserdrucker?', 2, '[{"text": "Ja", "correct": true, "because": "LED-Technologie reduziert Bauteile"}, {"text": "Nein", "correct": false, "because": "Größe ist typischerweise kleiner"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Auswahl eines LED-Druckers am wichtigsten?', 3, '[{"text": "Druckanforderungen", "correct": true, "because": "Bestimmen Volumen und Qualität"}, {"text": "Marke", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie ersetzt den Laser in LED-Druckern?', 2, '[{"text": "LED-Leiste", "correct": true, "because": "Erzeugt Bild durch Licht"}, {"text": "Tintenstrahl", "correct": false, "because": "Andere Technik"}, {"text": "Thermotransfer", "correct": false, "because": "Für Etikettendrucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verbrauchsmaterial ist für LED-Drucker essenziell?', 2, '[{"text": "Toner", "correct": true, "because": "Überträgt Farbe aufs Papier"}, {"text": "Tinte", "correct": false, "because": "Für Tintenstrahldrucker"}, {"text": "Farbband", "correct": false, "because": "Für Impactdrucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung ist typisch für LED-Drucker?', 3, '[{"text": "Bürodruck", "correct": true, "because": "Schnell und effizient für Dokumente"}, {"text": "Fotodruck", "correct": false, "because": "Tintenstrahl besser geeignet"}, {"text": "3D-Druck", "correct": false, "because": "Andere Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von LED-Druckern gegenüber Laserdruckern?', 2, '[{"text": "Kompaktere Bauweise", "correct": true, "because": "Weniger bewegliche Teile"}, {"text": "Geringere Anschaffungskosten", "correct": false, "because": "Kosten ähnlich"}, {"text": "Bessere Farbqualität", "correct": false, "because": "Qualität vergleichbar"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte beeinflussen die Auswahl eines LED-Druckers?', 4, '[{"text": "Druckvolumen", "correct": true, "because": "Bestimmt Kapazität"}, {"text": "Druckqualität", "correct": true, "because": "Beeinflusst Lesbarkeit"}, {"text": "Energieeffizienz", "correct": true, "because": "Reduziert Betriebskosten"}, {"text": "Gewicht des Druckers", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten LED-Drucker?', 3, '[{"text": "Hohe Druckgeschwindigkeit", "correct": true, "because": "Schnell wie Laser"}, {"text": "Energieeffizienz", "correct": true, "because": "Weniger Verbrauch"}, {"text": "Kompakte Größe", "correct": true, "because": "Weniger Bauteile"}, {"text": "Geringere Wartung", "correct": false, "because": "Wartung ähnlich wie Laser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Auswahl eines LED-Druckers auftreten?', 3, '[{"text": "Inkompatibilität mit Toner", "correct": true, "because": "Falscher Toner unbrauchbar"}, {"text": "Unzureichende Geschwindigkeit", "correct": true, "because": "Bei hohem Volumen"}, {"text": "Hohe Anschaffungskosten", "correct": true, "because": "Kann teuer sein"}, {"text": "Falsche Farbe", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen können LED-Drucker unterstützen?', 4, '[{"text": "USB", "correct": true, "because": "Standardverbindung"}, {"text": "Ethernet", "correct": true, "because": "Für Netzwerk"}, {"text": "Wi-Fi", "correct": true, "because": "Drahtlose Option"}, {"text": "HDMI", "correct": false, "because": "Für Video, nicht Drucker"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von LED-Druckern?', 3, '[{"text": "Bürodokumente", "correct": true, "because": "Schnell und effizient"}, {"text": "Marketingmaterial", "correct": true, "because": "Gute Qualität"}, {"text": "Textdruck in Großserien", "correct": true, "because": "Hohe Geschwindigkeit"}, {"text": "3D-Modelle", "correct": false, "because": "Falsche Technologie"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) LED-Drucker verwenden Toner statt Tinte. b) Sie sind langsamer als Tintenstrahldrucker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Toner ja, schneller als Tintenstrahl"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) LED-Drucker sind energieeffizienter als Laserdrucker. b) Druckqualität ist bei LED-Druckern geringer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ja, Qualität vergleichbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) LED-Drucker haben weniger bewegliche Teile als Laserdrucker. b) Sie sind für Fotodruck optimiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Weniger Teile ja, Fotodruck nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Netzwerkfähigkeit ist bei LED-Druckern nützlich. b) LED-Drucker sind für Großserien ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerk ja, Großserien möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) LED-Drucker bieten hohe Druckgeschwindigkeit. b) Toner ist bei LED-Druckern optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit ja, Toner nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

